const buildPaymentBillFilter = (params: any) => {
    const filter: { [k: string]: any } = {};

    if ("merchantId" in params) {
        filter["merchantInfo.id"] = params.merchantId;
    }

    if ("channelID" in params) {
        filter.$or = [
            { channelID: params.channelID },
            { "payments.channelID": params.channelID }
        ];
    }

    if ("merchantEmail" in params && params.merchantEmail) {
        filter["merchantInfo.email"] = buildRegexSearch(params.merchantEmail);
    }

    const directFields = ["apiType", "state", "serviceCode"];
    directFields.forEach(field => {
        if (field in params) {
            filter[field] = params[field];
        }
    });

    const regexFields = ["partnerCode", "orderId", "trackingId", "merchantTransId"];
    regexFields.forEach(field => {
        if (field in params && params[field]) {
            filter[field] = buildRegexSearch(params[field]);
        }
    });

    if ("payerMerchantCode" in params && params.payerMerchantCode) {
        filter["transactionParties.payer.merchantCode"] = buildRegexSearch(params.payerMerchantCode);
    }

    if ("payeeMerchantCode" in params && params.payeeMerchantCode) {
        filter["transactionParties.payee.merchantCode"] = buildRegexSearch(params.payeeMerchantCode);
    }

    if ("dateFr" in params || "dateTo" in params) {
        filter.createdAt = {};
        if ("dateFr" in params) {
            filter.createdAt.$gte = new Date(params.dateFr);
        }
        if ("dateTo" in params) {
            filter.createdAt.$lte = new Date(params.dateTo);
        }
    }

    if ("updatedFr" in params || "updatedTo" in params) {
        filter.lastUpdatedAt = {};
        if ("updatedFr" in params) {
            filter.lastUpdatedAt.$gte = new Date(params.updatedFr);
        }
        if ("updatedTo" in params) {
            filter.lastUpdatedAt.$lte = new Date(params.updatedTo);
        }
    }

    filter.isDelete = false;
    return filter;
};

